<script setup lang="ts">
import { computed, ref } from 'vue'
import { NoratoTabs, type NoratoTab } from '@norato/vue'
import PlaygroundSelect from './PlaygroundSelect.vue'
const props = defineProps<{ copiedKey: string }>()
const emit = defineEmits<{ copy: [key: string, value: string] }>()
const selected = ref('all'), style = ref<'line'|'soft'>('line'), orientation = ref<'horizontal'|'vertical'>('horizontal'), size = ref<'small'|'medium'|'large'>('medium'), disabled = ref(false)
const tabs: NoratoTab[] = [{value:'all',label:'همه',count:12,content:'همهٔ پروژه‌ها؛ ۱۲ مورد'}, {value:'active',label:'فعال',count:8,content:'پروژه‌های فعال؛ ۸ مورد'}, {value:'archived',label:'بایگانی',content:'پروژه‌های بایگانی‌شده'}, {value:'drafts',label:'پیش‌نویس',disabled:true,content:'پروژه‌های پیش‌نویس'}]
const snippet = computed(() => `<script setup lang="ts">\nimport { ref } from 'vue'\nimport { NoratoTabs, type NoratoTab } from '@norato/vue'\nconst selected = ref('all')\nconst tabs: NoratoTab[] = ${JSON.stringify(tabs.map(({value,label,count,content,disabled:off})=>({value,label,...(count!==undefined?{count}:{}),...(off?{disabled:off}:{}),content})),null,2)}\n<\/script>\n<template><NoratoTabs id="projects-tabs" v-model="selected" label="پروژه‌ها" :tabs="tabs"><template #panel-all>محتوای اختصاصی پنل</template></NoratoTabs></template>`)
</script>
<template><div class="button-playground tabs-playground" dir="rtl"><header><strong>آزمایش Tabs اجرایی</strong><span>انتخاب، پنل‌ها، سبک، اندازه، جهت و تب غیرفعال را بررسی کن.</span></header><div class="button-playground-preview tabs-playground-preview"><NoratoTabs id="tabs-playground" v-model="selected" label="پروژه‌ها" :tabs="tabs" :style="style" :size="size" :orientation="orientation" :disabled="disabled"><template #panel-all>نمایش {{ selected }} · ۱۲ پروژه</template><template #panel-active>۸ پروژهٔ فعال</template><template #panel-archived>پروژه‌های بایگانی‌شده</template></NoratoTabs></div><div class="button-playground-controls"><PlaygroundSelect id="tabs-style" v-model="style" label="سبک" :options="[{value:'line',label:'Line'},{value:'soft',label:'Soft'}]"/><PlaygroundSelect id="tabs-size" v-model="size" label="اندازه" :options="[{value:'small',label:'Small'},{value:'medium',label:'Medium'},{value:'large',label:'Large'}]"/><PlaygroundSelect id="tabs-orientation" v-model="orientation" label="جهت" :options="[{value:'horizontal',label:'افقی'},{value:'vertical',label:'عمودی'}]"/><label class="button-playground-switch"><input v-model="disabled" type="checkbox"/><span class="button-playground-track" aria-hidden="true"><span/></span><span>همه غیرفعال</span></label></div><div class="button-playground-code"><div class="button-playground-codebar"><strong>کد Vue</strong><button class="copy-section-button" type="button" @click="emit('copy','tabs-playground',snippet)">{{ props.copiedKey==='tabs-playground'?'کپی شد':'کپی کد' }}</button></div><pre class="usage-code" dir="ltr"><code>{{ snippet }}</code></pre></div></div></template>
